  const [guideDownload,setGuideDownload]=useState<{url:string;filename:string}|null>(null);useEffect(()=>{let active=true,url:string|undefined;if(!data||!interpretation||!design||!guardrails||!candidate||!validation||!trace||!deploymentGuideEligible(candidate,design,validation,guardrails)){setGuideDownload(null);return()=>{active=false}}void import('./deploymentGuide').then(({generateDeploymentGuide})=>generateDeploymentGuide({run:{id:trace.runId,generatedAt:trace.startedAt,applicationVersion:candidate.generatorVersion},interpretation,data,design,tenant,policy:guardrails,candidate,validation})).then(guide=>{if(!active)return;url=URL.createObjectURL(new Blob([guide.bytes],{type:'application/pdf'}));setGuideDownload({url,filename:guide.filename})}).catch(()=>{if(active)setGuideDownload(null)});return()=>{active=false;if(url)URL.revokeObjectURL(url)}},[data,interpretation,design,tenant,guardrails,candidate,validation,trace]);
