  const applyAnalysis=async(active:ClarificationSession,rag:RagRetrieval)=>{if(!data)return active;const result=await analyseRequirementIteratively({session:active,schema:summarizeDataStructure(data),tenant,mode:active.mode,knowledge:clarificationKnowledgeContext(rag,documents)}),next=applyClarificationAnalysis(active,{...result.value,analysedAt:new Date().toISOString()});setSession(next);setInterpretation(result.value.interpretation);setInterpretMetrics(current=>combineAIMetrics(current,result.metrics));setAnswers({});setTrace(current=>mergeTrace(current,{interpretation:combineAIMetrics(current?.interpretation??null,result.metrics),clarificationState:next.state,clarificationRounds:next.rounds.length,clarificationCount:next.rounds.reduce((sum,round)=>sum+round.questions.length,0),finalStatus:next.state}));if(['HUMAN_REVIEW_REQUIRED','UNSUPPORTED','OUT_OF_SCOPE'].includes(next.state)){let status:string=next.state;if(next.state==='OUT_OF_SCOPE'){const decision=evaluateGuardrails(result.value.interpretation,null,data,tenant);setGuardrails(decision);status=decision.outcome;setTrace(current=>mergeTrace(current,{guardrails:decision.evaluations,finalStatus:status}))}onRun({runId:next.sessionId,timestamp:new Date().toISOString(),requirement:next.originalRequest,fileName:data.fileName,status,clarificationCount:next.rounds.reduce((sum,round)=>sum+round.questions.length,0),model:result.metrics.model,tokens:result.metrics.totalTokens,latencyMs:result.metrics.latencyMs})}return next};
